};

export function flattenWorkflowRunPages(data?: InfiniteData<TWorkflowRunListPage>): TWorkflowRunListItem[] {
  return data?.pages.flatMap((page) => page.data) ?? [];
}

export function removeWorkflowFromInfiniteData(
  data: InfiniteData<TWorkflowListPage> | undefined,
  workflowId: string
): InfiniteData<TWorkflowListPage> | undefined {
  if (!data) {
    return data;
  }

  let workflowWasRemoved = false;

  const pages = data.pages.map((page) => {
    const nextData = page.data.filter((workflow) => workflow.id !== workflowId);
    if (nextData.length !== page.data.length) {
      workflowWasRemoved = true;
    }

    return { ...page, data: nextData };
  });

  if (!workflowWasRemoved) {
    return data;
  }

  return { ...data, pages };
}

import { z } from "zod";
import { V3_LIST_DEFAULT_LIMIT, V3_LIST_MAX_LIMIT } from "@/app/api/v3/lib/cursor-pagination";

/**
 * Shared query schema for workspace-scoped v3 reference-list endpoints (action classes, contact
 * attribute keys): a required `workspaceId` plus the standard cursor-pagination `limit` + `cursor`.
 */
export const ZV3WorkspaceListQuery = z
  .object({
    workspaceId: z.cuid2(),
    limit: z.coerce.number().int().min(1).max(V3_LIST_MAX_LIMIT).default(V3_LIST_DEFAULT_LIMIT),
    cursor: z.string().min(1).optional(),
  })
  .strict();

export type TV3WorkspaceListQuery = z.infer<typeof ZV3WorkspaceListQuery>;

/**
 * For operations that accept no query parameters at all. `.strict()` is the point: without it an
 * unrecognized parameter is silently ignored, and a silently-ignored filter returns more data than the
 * caller believes they asked for.
 *
 * Lived in `surveys/schemas.ts` until the response operations needed it too; it was never
 * survey-specific.
 */
export const ZV3EmptyQuery = z.object({}).strict();

import "server-only";
import { logger } from "@formbricks/logger";
import { InvalidInputError } from "@formbricks/types/errors";
import { requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { paginateByIdCursor } from "@/app/api/v3/lib/cursor-pagination";
import { mapV3ThrownError } from "@/app/api/v3/lib/errors";
import { problemBadRequest, successListResponse } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";

/** Shared params for the workspace-scoped v3 reference-list endpoints (action classes, attribute keys). */
export type TV3WorkspaceListParams = {
  workspaceId: string;
  limit: number;
  cursor?: string;
  authentication: TV3Authentication;
  requestId: string;
  instance: string;
};

type TListV3WorkspaceResourceConfig<TRow extends { id: string }, TOut> = TV3WorkspaceListParams & {
  /** Human-readable resource name; used only in error logs. */
  resourceName: string;
  /** Fetch the workspace's full list (request-deduped); it is paginated in memory below. */
  fetchAll: (workspaceId: string) => Promise<readonly TRow[]>;
  /** Map a fetched row to its public response shape. */
  serialize: (row: TRow) => TOut;
  /** Optional entitlement gate, run after auth: return a Response to short-circuit (e.g. 403), or null to allow. */
  assertEntitlement?: (workspaceId: string) => Promise<Response | null>;
};

/**
 * Shared handler for the workspace-scoped v3 reference-list endpoints. Resolves workspace access,
 * runs an optional entitlement gate, fetches the full list and paginates it in memory — these are
 * bounded reference collections the codebase already reads as a whole (request-deduped via React
 * cache), so they don't fork the canonical read with a DB-side `take`/`cursor` query (see
 * paginateByIdCursor). A malformed cursor maps to 400; any other failure to 500.
 */
export async function listV3WorkspaceResource<TRow extends { id: string }, TOut>(
  config: TListV3WorkspaceResourceConfig<TRow, TOut>
): Promise<Response> {
  const {
    workspaceId,
    limit,
    cursor,
    authentication,
    requestId,
    instance,
    resourceName,
    fetchAll,
    serialize,
  } = config;
  const log = logger.withContext({ requestId, workspaceId });

  try {
    const authResult = await requireV3WorkspaceAccess(
      authentication,
      workspaceId,
      "read",
      requestId,
      instance
    );
    if (authResult instanceof Response) {
      return authResult;
    }

    if (config.assertEntitlement) {
      const denied = await config.assertEntitlement(authResult.workspaceId);
      if (denied) {
        return denied;
      }
    }

    const rows = await fetchAll(authResult.workspaceId);
    const { page, nextCursor } = paginateByIdCursor(rows, { limit, cursor });

    return successListResponse(
      page.map(serialize),
      { limit, nextCursor },
      { requestId, cache: "private, no-store" }
    );
  } catch (err) {
    if (err instanceof InvalidInputError) {
      log.warn({ statusCode: 400 }, "Invalid pagination cursor");
      return problemBadRequest(requestId, err.message, {
        invalid_params: [{ name: "cursor", reason: err.message }],
        instance,
      });
    }
    // Dotted and machine-readable, like every other `operation` label: `resourceName` is human prose
    // ("action classes"), which would log `operation: "action classes.list"` and break grouping.
    const operation = `${resourceName.replace(/\s+/g, "-")}.list`;
    return mapV3ThrownError(err, { log, requestId, instance, operation });
  }
}

