  const triggerMap: Record<string, string> = {
    responseFinished: t(\"workspace.integrations.webhooks.response_finished\"),
    responseCreated: t(\"workspace.integrations.webhooks.response_created\"),
    responseUpdated: t(\"workspace.integrations.webhooks.response_updated\"),
  };

  return webhook.triggers.map((trigger) => triggerMap[trigger] ?? trigger).join(\" | \");
};

