import { getWebhook } from "@/modules/api/v2/management/webhooks/[webhookId]/lib/webhook";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import { createWebhook } from "@/modules/integrations/webhooks/lib/webhook";
import { successResponse } from "@/app/api/v3/lib/response";
import { ZWebhookWithoutSecret } from "@formbricks/database/zod/webhooks";

const ZDuplicateWebhookBody = z
  .object({
    name: z.string().optional(),
  })
  .strict();

const ZWebhookIdParam = z.object({
  webhookId: ZId,
});

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "webhook",
  schemas: {
    params: ZWebhookIdParam,
    body: ZDuplicateWebhookBody,
  },
  handler: async ({
    parsedInput,
    authentication,
    auditLog,
    requestId,
    instance,
  }) => {
    const { webhookId } = parsedInput.params;
    const workspaceId = await getWorkspaceIdFromWebhookId(webhookId);

    await assertCan({ type: "user", id: authentication.userId }, "workspace.write", {
      type: "workspace",
      id: workspaceId,
    });

    await applyRateLimit(rateLimitConfigs.actions.stateMutation, workspaceId);

    const organizationId = await getOrganizationIdFromWorkspaceId(workspaceId);

    auditLog.organizationId = organizationId;
    auditLog.targetId = webhookId;

    const webhookResult = await getWebhook(webhookId);
    if (!webhookResult.ok) {
      throw new ResourceNotFoundError("Webhook", webhookId);
    }

    const originalWebhook = webhookResult.data;
    const newWebhook = await createWebhook(
      workspaceId,
      {
        name: parsedInput.body.name ?? `${originalWebhook.data.name || originalWebhook.data.url} (Copy)`,
        url: originalWebhook.data.url,
        source: "user",
        triggers: originalWebhook.data.triggers,
        surveyIds: originalWebhook.data.surveyIds,
      },
      undefined // generate a new secret
    );

    auditLog.newObject = ZWebhookWithoutSecret.parse(newWebhook);

    return successResponse(ZWebhookWithoutSecret.parse(newWebhook));
  },
});

import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import { ZWebhookWithoutSecret } from "@formbricks/database/zod/webhooks";
import type { z } from "zod";

export type TWebhookResource = z.infer<typeof ZWebhookWithoutSecret>;

const MUTATION_TIMEOUT_MS = 15_000;

/**
 * Duplicate an existing webhook, creating a new one with the same configuration.
 *
 * @param webhookId - ID of the webhook to duplicate
 * @param name - Optional custom name for the duplicate; defaults to "<original name> (Copy)"
 * @returns The newly created webhook resource
 */
export async function duplicateWebhook(
  webhookId: string,
  name?: string
): Promise<TWebhookResource> {
  const response = await fetch(`/api/v3/webhooks/${encodeURIComponent(webhookId)}/duplicate`, {
    method: "POST",
    cache: "no-store",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(name ? { name } : {}),
    signal: AbortSignal.timeout(MUTATION_TIMEOUT_MS),
  });

  if (!response.ok) {
    throw await parseV3ApiError(response);
  }

  const body = (await response.json()) as { data: TWebhookResource };
  return body.data;
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { duplicateWebhook } from "@/modules/integrations/webhooks/lib/api-client";

/**
 * Mutation hook for duplicating a webhook via the v3 API.
 *
 * Invalidates the workspace's webhook list after a successful mutation so the
 * server component's data stays in sync without a full page reload.
 */
export const useDuplicateWebhook = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ webhookId, name }: { webhookId: string; name?: string }) =>
      duplicateWebhook(webhookId, name),
    onSettled: () => {
      // Invalidate all webhook-related queries so the next render picks up the new row.
      queryClient.invalidateQueries({ queryKey: ["webhooks"] });
    },
  });
};

